def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 8.0))

    total_agents = 1 + len(alive)
    likely_winners = int(supply // WATER_REQ)
    if likely_winners < 1:
        likely_winners = 1

    prev_bids = []
    danger_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0.0)
            prev_bids.append(bid)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    highest_danger = max(danger_bids) if danger_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    scarcity = total_agents - likely_winners

    if urgency >= 5:
        bid = max(92.0, highest_danger + 3.0, avg_prev + 8.0)
    elif urgency >= 3:
        bid = max(72.0, min(96.0, highest_danger + 2.0), avg_prev * 0.9 + 6.0)
    else:
        if scarcity <= 0:
            bid = 9.0
        elif likely_winners >= 2:
            bid = max(18.0, min(52.0, avg_prev * 0.45 + 4.0))
        else:
            if highest_prev >= 140.0:
                bid = 24.0
            elif highest_prev >= 100.0:
                bid = 34.0
            elif highest_prev >= 70.0:
                bid = 46.0
            else:
                bid = 41.0

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid *= 0.9

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.82)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 88.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday's bids to infer who is willing/able to pay.
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure proxy: if any opponent bid very high yesterday, they likely needed water urgently.
    high_bid = max(prev_bids) if prev_bids else 0.0

    # Cash constraint proxy from yesterday: if an opponent's budget_after was near zero, they can't outbid much.
    # Use only previous_trace.
    cash_starved = 0
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        ba = prev.get('budget_after', None)
        hb = prev.get('hp_after', None)
        if ba is not None:
            try:
                if float(ba) <= 1.0:
                    cash_starved += 1
            except Exception:
                pass
        # If they already had low hp_after, they may bid aggressively again.
        if hb is not None:
            try:
                if float(hb) <= 2.0:
                    cash_starved += 0  # keep separate from cash
            except Exception:
                pass

    # Base bid depends on supply: lower supply => more competitive.
    # Map supply to a competitiveness factor in [0,1].
    if MAX_SUPPLY == MIN_SUPPLY:
        comp = 0.5
    else:
        comp = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    comp = max(0.0, min(1.0, comp))

    # Urgency: if we've gone multiple days without water or low hp, bid harder.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.7
    elif hp <= 4.0:
        urgency += 0.4
    if no_water_days >= 2:
        urgency += 0.4
    elif no_water_days == 1:
        urgency += 0.2

    # Strategy: target just below the strongest yesterday bidder when opponents are cash-starved.
    # Otherwise bid moderately.
    target = DAILY_SALARY * (0.35 + 0.35 * comp + 0.25 * urgency)

    if high_bid > 0.0:
        # If someone bid very high yesterday, try to contest but not fully match unless we're urgent.
        if high_bid >= DAILY_SALARY * 0.85:
            if urgency >= 0.5:
                target = max(target, high_bid * 0.85)
            else:
                target = max(target, high_bid * 0.55)
        else:
            target = max(target, high_bid * (0.45 + 0.25 * comp))

    # If many opponents appear cash-starved, we can bid lower and still win.
    if cash_starved >= 2:
        target *= 0.85

    # Never exceed budget.
    bid = max(0.0, min(budget, target))

    # If budget is very small, bid all-in.
    if budget <= DAILY_SALARY * 0.1:
        bid = min(budget, DAILY_SALARY * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_no_water_days > 0:
        base_bid = DAILY_SALARY * 0.85
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75

    if current_supply < WATER_REQ * 2 and num_alive_opponents > 0:
        base_bid *= 1.15
    elif current_supply >= WATER_REQ * 2 and num_alive_opponents > 0:
        base_bid *= 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.4:
            base_bid = max(base_bid, highest_prev_bid + 1)

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2:
        if my_hp <= 3:
            base_bid = DAILY_SALARY * 1.0
        elif my_budget > DAILY_SALARY * 2:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_budget, base_bid)

    if final_bid <= 0 and my_budget > 0:
        final_bid = min(my_budget, 1.0)

    return max(0.0, final_bid)

